messages.content:
Determine team mode

Answer with one JSON object that matches this JSON schema, and nothing else: no code fence, no text around it.
<json_schema>
{
  "description": "AI decision for team collaboration mode.",
  "properties": {
    "mode": {
      "description": "coordinate for delegation and synthesis, collaborate for all working on same task",
      "enum": [
        "coordinate",
        "collaborate"
      ],
      "title": "Mode",
      "type": "string"
    },
    "reasoning": {
      "description": "Brief explanation of why this mode was chosen",
      "title": "Reasoning",
      "type": "string"
    }
  },
  "required": [
    "mode",
    "reasoning"
  ],
  "title": "_TeamModeDecision",
  "type": "object"
}
</json_schema>
